import fs from "node:fs/promises";
import path from "node:path";

/**
 * Synthesized fixtures of delegated copies' own files as the released code writes them before
 * `20261019_delegated_copy_own_file_complete_v1` (design Shape Inventory, F-A1..F-T4): hand-built JSON in the shapes of
 * `legacy/released-run-package-shapes/released-task-agent-own-files-with-origin.ts` (the 10-17 output and the runtime
 * writers since), never generated by current code and never copied from user data. Coordinating trees are in their
 * current on-disk shape (links), with configured slots whose launch objects may carry the obsolete `skillAccessMode`.
 */

type Json = Record<string, unknown>;
export const T0 = "2026-10-17T09:00:00.000Z";
export const launch = { runtimeKind: "codex_app_server", llmModelIdentifier: "gpt-5", llmConfig: { reasoning_effort: "medium" }, autoExecuteTools: true, workspaceRootPath: "/work/project" };
export const otherLaunch = { runtimeKind: "claude_agent_sdk", llmModelIdentifier: "opus", llmConfig: null, autoExecuteTools: false, workspaceRootPath: "/work/other" };
/** A released slot launch object: the 5 current keys plus the obsolete `skillAccessMode`. */
export const slotLaunch = (overrides: Json = {}): Json => ({ ...launch, skillAccessMode: "PRELOADED_ONLY", ...overrides });
export const edit = { llmModelIdentifier: "gpt-5-mini", llmConfig: null, selectedAt: "2026-10-17T10:00:00.000Z" };
export const fallback = { layer: "agent_default", runtimeKind: "grok_build", llmModelIdentifier: "grok-4", reason: "runtime_unavailable", detail: "no grok" };

export type Coordinating = Readonly<{ kind: "agent" | "agent_team" | "agent_org"; runId: string }>;

export const put = async (file: string, value: unknown): Promise<void> => {
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, typeof value === "string" ? value : `${JSON.stringify(value, null, 2)}\n`);
};

const section = (input: Readonly<{ coordinating: Coordinating; address: string; origin: string; delegator?: string; launchSource?: Json; userLaunchSelection?: Json }>) => ({
  coordinatingRun: input.coordinating,
  ...(input.delegator === undefined ? {} : { delegatorAgentRunId: input.delegator }),
  address: input.address,
  origin: input.origin,
  ...(input.launchSource === undefined ? {} : { launchSource: input.launchSource }),
  ...(input.userLaunchSelection === undefined ? {} : { userLaunchSelection: input.userLaunchSelection }),
});

/** A released agent own file (`run_metadata.json` with `taskAgent.origin`); `launch: null` is the 10-17 configured-place output. */
export const releasedAgentOwnFile = (memory: string, runId: string, input: Readonly<{
  coordinating: Coordinating; address: string; origin: "catalog" | "configured_place"; agentDefinitionId: string;
  launch: Json | null; delegator?: string; launchSource?: Json; userLaunchSelection?: Json; platformAgentRunId?: string | null;
}>): Json => ({
  runId,
  agentDefinitionId: input.agentDefinitionId,
  workspaceRootPath: input.launch?.workspaceRootPath ?? null,
  memoryDir: path.join(memory, "agents", runId),
  llmModelIdentifier: input.launch?.llmModelIdentifier ?? null,
  llmConfig: input.launch?.llmConfig ?? null,
  autoExecuteTools: input.launch?.autoExecuteTools ?? null,
  runtimeKind: input.launch?.runtimeKind ?? null,
  platformAgentRunId: input.platformAgentRunId ?? null,
  startedAt: T0,
  taskAgent: section(input),
});

export type ReleasedMember = Readonly<{ name: string; agentDefinitionId?: string; launchConfiguration?: Json; launchSource?: Json; userLaunchSelection?: Json }>;

/** A released task agent team's own tree: members carry a launch only when recorded (catalog: their own default). */
export const releasedTeamOwnTree = (teamRunId: string, input: Readonly<{
  coordinating: Coordinating; address: string; origin: "catalog" | "configured_place"; teamDefinitionId: string;
  members: readonly ReleasedMember[]; defaultLaunchConfiguration?: Json; handoffs?: readonly Json[];
  delegator?: string; launchSource?: Json; userLaunchSelection?: Json;
}>): Json => ({
  createdAt: T0,
  archivedAt: null,
  applicationBinding: null,
  handoffs: input.handoffs ?? [],
  rootTeam: {
    address: input.address,
    teamDefinitionId: input.teamDefinitionId,
    teamRunId,
    coordinatorAddress: `${input.address}/${input.members[0]!.name}`,
    defaultLaunchConfiguration: input.defaultLaunchConfiguration ?? launch,
    members: input.members.map((member) => ({
      address: `${input.address}/${member.name}`,
      agentDefinitionId: member.agentDefinitionId ?? member.name,
      agentRunId: `${teamRunId}-${member.name}`,
      platformAgentRunId: null,
      role: null,
      description: null,
      ...(member.launchConfiguration === undefined ? {} : { launchConfiguration: member.launchConfiguration }),
      ...(member.launchSource === undefined ? {} : { launchSource: member.launchSource }),
      ...(member.userLaunchSelection === undefined ? {} : { userLaunchSelection: member.userLaunchSelection }),
    })),
    taskExecutions: [],
  },
  taskAgent: section(input),
});

/** A configured agent slot as a coordinating tree records it (launch possibly with `skillAccessMode`). */
export const configuredAgent = (address: string, agentRunId: string, agentDefinitionId: string, launchConfiguration: Json = slotLaunch()): Json => ({
  address, agentDefinitionId, role: null, description: null, agentRunId, platformAgentRunId: `slot-session-${agentRunId}`, launchConfiguration,
});

export const link = (address: string, id: Readonly<{ agentRunId: string } | { teamRunId: string }>, delegator?: string): Json => ({
  address, ...id, ...(delegator === undefined ? {} : { delegatorAgentRunId: delegator }), startedAt: T0,
});

/** A Team run's tree on disk (links to its task agents) and its empty message log. */
export const writeTeamRun = async (memory: string, teamRunId: string, input: Readonly<{ members: readonly Json[]; links: readonly Json[]; handoffs?: readonly Json[] }>) => {
  const dir = path.join(memory, "agent_teams", teamRunId);
  await put(path.join(dir, "team_run_execution_tree.json"), {
    createdAt: T0, archivedAt: null, applicationBinding: null, handoffs: input.handoffs ?? [],
    rootTeam: { address: "/", teamDefinitionId: "writing-team", teamDefinitionName: "Writing Team", teamRunId,
      coordinatorAddress: input.members[0]!.address, defaultLaunchConfiguration: slotLaunch(), members: input.members, taskExecutions: input.links },
  });
  await put(path.join(dir, "team_communication_messages_active.jsonl"), "");
  return dir;
};

/** An Org run's tree on disk: direct agents and mounted teams (`{ team, members }`), links at the root. */
export const writeOrgRun = async (memory: string, orgRunId: string, input: Readonly<{ members: readonly Json[]; links: readonly Json[]; handoffs?: readonly Json[] }>) => {
  const dir = path.join(memory, "agent_orgs", orgRunId);
  await put(path.join(dir, "agent_org_run_execution_tree.json"), {
    subjectKind: "agent_org", createdAt: T0, archivedAt: null, applicationBinding: null, handoffs: input.handoffs ?? [],
    rootOrg: { address: "/", orgDefinitionId: "company", orgDefinitionName: "Company", orgRunId, defaultLaunchConfiguration: slotLaunch(),
      members: input.members, taskExecutions: input.links },
  });
  await put(path.join(dir, "agent_org_communication_messages_active.jsonl"), "");
  return dir;
};

/** A mounted Team of an Org (its members' launch objects as given). */
export const mountedTeam = (address: string, teamRunId: string, defaultLaunchConfiguration: Json, members: readonly Json[]): Json => ({
  address, teamDefinitionId: "student-study-group", role: null, description: null, teamRunId,
  coordinatorAddress: (members[0] as { address: string }).address, defaultLaunchConfiguration, members, taskExecutions: [],
});

/** An Agent run (hub) with its collaboration tree of links. */
export const writeHub = async (memory: string, hubRunId: string, links: readonly Json[]) => {
  const runDir = path.join(memory, "agents", hubRunId);
  await put(path.join(runDir, "run_metadata.json"), { runId: hubRunId, agentDefinitionId: "assistant", workspaceRootPath: "/work/project",
    memoryDir: runDir, llmModelIdentifier: "gpt-5", llmConfig: null, autoExecuteTools: true, runtimeKind: "codex_app_server", platformAgentRunId: null, startedAt: T0 });
  const dir = path.join(runDir, "collaboration");
  await put(path.join(dir, "collaboration_tree.json"), { subjectKind: "agent", createdAt: T0,
    host: { address: "/assistant", agentRunId: hubRunId, agentDefinitionId: "assistant" }, taskExecutions: links });
  await put(path.join(dir, "communication_messages_active.jsonl"), "");
  return dir;
};

export const agentFile = (memory: string, runId: string) => path.join(memory, "agents", runId, "run_metadata.json");
export const teamFile = (memory: string, teamRunId: string) => path.join(memory, "agent_teams", teamRunId, "team_run_execution_tree.json");
export const readJson = async (file: string): Promise<any> => JSON.parse(await fs.readFile(file, "utf8"));
/** The 5 current launch keys of a slot launch object (what the migration writes). */
export const projected = (value: Json): Json => ({
  runtimeKind: value.runtimeKind, llmModelIdentifier: value.llmModelIdentifier, llmConfig: value.llmConfig,
  autoExecuteTools: value.autoExecuteTools, workspaceRootPath: value.workspaceRootPath,
});
